local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end
local hooks={};local hookapi={Add=function(e,n,f)hooks[e.."/"..n]=f end,Remove=function(e,n)hooks[e.."/"..n]=nil end};local timerapi={Simple=function(d,f)f()end};local now=0
local function valid(x)return type(x)=="table"and x.valid~=false end
local function player(fail)local p={valid=true,weapons={},ammo={},calls={},fail=fail};function p:IsPlayer()return true end;function p:StripWeapons()self.calls[#self.calls+1]="strip";self.weapons={}end;function p:RemoveAllAmmo()self.calls[#self.calls+1]="reset-ammo";self.ammo={}end;function p:Give(c,noammo)self.calls[#self.calls+1]="give:"..c;assert(noammo==true);if self.fail==c then return nil end;local w={valid=true,class=c};self.weapons[c]=w;return w end;function p:GiveAmmo(n,t)self.calls[#self.calls+1]="ammo:"..t;self.ammo[t]=(self.ammo[t]or 0)+n end;function p:SelectWeapon(c)self.calls[#self.calls+1]="select:"..c;self.selected=c end;return p end
local bindings;local function include()return load_submission("lua/rhenium_loadout_profiles/profiles.lua",bindings)end;bindings={include=include,hook=hookapi,timer=timerapi,IsValid=valid,CurTime=function()return now end};local S=load_submission("lua/rhenium_loadout_profiles/server.lua",bindings);local a=player()
local spec={weapons={{class="weapon_pistol",primary={type="Pistol",amount=40}},{class="weapon_smg1",primary={type="SMG1",amount=60},secondary={type="SMG1",amount=10}}}}
case("adapter installs only meaningful spawn and disconnect hooks",function()S.Install({});assert(hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"]);assert(hooks["PlayerDisconnected/"..S.HookPrefix..".Disconnect"]);assert(not hooks["PlayerInitialSpawn/"..S.HookPrefix..".Initial"]);assert(not hooks["PlayerDeath/"..S.HookPrefix..".Death"]);assert(S.TimerName==nil)end)
case("trusted binding overrides all payload identity",function()assert(S.BindPlayer(a,"A"));assert(S.HandlePut(a,"put","x",spec,1));assert(S.HandleSelect(a,"sel","x",1))end)
case("Apply orders Strip Give Ammo and selection",function()local ok,c=S.Apply(a);assert(ok,c);assert(a.calls[1]=="strip"and a.calls[2]=="reset-ammo"and a.calls[3]:find("give:")and a.calls[#a.calls]:find("select:"))end)
case("shared ammo is granted once at the merged amount",function()assert(a.ammo.SMG1==70 and a.calls[5]=="ammo:Pistol"and a.calls[6]=="ammo:SMG1")end)
case("spawn hook reapplies without accumulating pickups",function()a.ammo.SMG1=999;hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"](a);assert(a.ammo.SMG1==70)end)
case("partial Give failure stops before ammo",function()local b=player("weapon_smg1");assert(S.BindPlayer(b,"B"));assert(S.HandlePut(b,"p2","x",spec,1));assert(S.HandleSelect(b,"s2","x",1));local ok,c=S.Apply(b);assert(not ok and c=="give_failed");assert(next(b.ammo)==nil)end)
case("disconnect removes object binding but retains profile",function()hooks["PlayerDisconnected/"..S.HookPrefix..".Disconnect"](a);local ok,c=S.Apply(a);assert(not ok and c=="unbound");local replacement=player();assert(S.BindPlayer(replacement,"A"));assert(S.Apply(replacement))end)
case("Install is idempotent",function()local spawn=hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"];S.Install({});assert(hooks["PlayerSpawn/"..S.HookPrefix..".Spawn"]==spawn)end)
case("shutdown removes all meaningful hooks",function()S.Shutdown();S.Shutdown();for k in pairs(hooks)do if k:find("RheniumLoadoutProfiles",1,true)then error("hook leak")end end end)
return{cases=cases}
